using FluentValidation; using IptvManagement.Application.DTOs;
namespace IptvManagement.Application.Validation;
public class CustomerUpsertDtoValidator:AbstractValidator<CustomerUpsertDto>{ public CustomerUpsertDtoValidator(){ RuleFor(x=>x.CustomerNumber).NotEmpty().MaximumLength(40).WithMessage("Die Kundennummer ist erforderlich."); RuleFor(x=>x.FirstName).NotEmpty().MaximumLength(100); RuleFor(x=>x.LastName).NotEmpty().MaximumLength(100); RuleFor(x=>x.Email).NotEmpty().EmailAddress().WithMessage("Bitte geben Sie eine gültige E-Mail-Adresse ein."); RuleFor(x=>x.Country).NotEmpty().Length(2); }}
public class PackageUpsertDtoValidator:AbstractValidator<PackageUpsertDto>{ public PackageUpsertDtoValidator(){ RuleFor(x=>x.Name).NotEmpty().MaximumLength(120); RuleFor(x=>x.Price).GreaterThanOrEqualTo(0); RuleFor(x=>x.DurationInMonths).GreaterThan(0); RuleFor(x=>x.MaxDevices).InclusiveBetween(1,50); RuleFor(x=>x.Currency).NotEmpty().Length(3); }}
public class ChannelUpsertDtoValidator:AbstractValidator<ChannelUpsertDto>{ public ChannelUpsertDtoValidator(){ RuleFor(x=>x.Name).NotEmpty().MaximumLength(160); RuleFor(x=>x.StreamUrl).NotEmpty().Must(u=>Uri.TryCreate(u,UriKind.Absolute,out var uri)&& (uri.Scheme=="https"||uri.Scheme=="http")).WithMessage("Die Stream-URL muss eine gültige absolute HTTP(S)-URL sein."); RuleFor(x=>x.CategoryId).NotEmpty(); RuleFor(x=>x.CountryCode).NotEmpty().Length(2); RuleFor(x=>x.LanguageCode).NotEmpty().MinimumLength(2).MaximumLength(8); RuleFor(x=>x.LicenseReference).NotEmpty().WithMessage("Eine Lizenzreferenz oder die Kennzeichnung als öffentlich verfügbar ist erforderlich."); }}
